<!-- Static DOM retained for existing feature runtime. Keep IDs and classes stable. -->
<template>
<section v-pre id="tprmRegisterView" class="view">
          <div class="page-heading"><div><p class="eyebrow">THIRD-PARTY RISK MANAGEMENT</p><h2>TPRM Risk Register</h2><p class="lede">Daftar vendor, service dependency, tier risiko, assessment status, dan jadwal review.</p></div><div class="csf-actions"><button class="button button-accent" id="tprmNewButton" type="button">New third party</button><span class="file-count" id="tprmCount">0 records</span></div></div>
          <div class="section-heading"><div><p class="eyebrow">THIRD-PARTY RISK REGISTER</p><h3>Third-party risk workspace</h3></div></div>
          <div class="excel-wrap"><table class="excel-table tprm-register-table"><thead><tr><th>Third party</th><th>Service / dependency</th><th>Vendor Due diligence risk</th><th>CIA Risk level</th><th>Related risk</th><th>Relationship status</th><th>Assessment status</th><th>Next review</th><th>Risk summary</th><th>Actions</th></tr></thead><tbody id="tprmBody"></tbody></table><div class="assessment-pagination" id="tprmPagination"></div></div>
          <dialog id="tprmModal" class="certification-modal"><form id="tprmForm" class="risk-register-form"><input id="tprmId" type="hidden"><div class="section-heading compact"><div><p class="eyebrow">TPRM RECORD</p><h3 id="tprmFormTitle">New third party</h3></div><span class="save-state" id="tprmStatus">Ready</span></div><div class="risk-register-grid"><label>Third party<select id="tprmThirdParty" required><option value="">Select vendor</option></select></label><label>Service / dependency<input id="tprmServiceDependency" required maxlength="240" placeholder="e.g. Cloud hosting, payroll, OT integration"></label><label>Due diligence risk<input id="tprmDueDiligenceRisk" readonly placeholder="Selected vendor risk tier"></label></div><label>Notes<textarea id="tprmNotes" rows="4"></textarea></label><div class="csf-form-actions"><button class="button button-accent" type="submit">Save record</button><button class="button button-danger" id="tprmDelete" type="button" hidden>Delete record</button><button class="button button-quiet" id="tprmCancel" type="button">Close</button></div></form></dialog>
          <dialog id="tprmAssessmentModal" class="certification-modal questionnaire-assessment-modal"><form id="tprmAssessmentForm" class="risk-register-form"><input id="tprmAssessmentId" type="hidden"><div class="section-heading compact"><div><p class="eyebrow">CIA DEVICE ONBOARDING ASSESSMENT</p><h3 id="tprmAssessmentTitle">Device assessment</h3></div><span class="save-state" id="tprmAssessmentStatus">Ready</span></div><fieldset class="questionnaire-section questionnaire-final-section"><legend>Inverted scoring: 1 = very high risk, 5 = very low risk</legend><div class="cia-assessment-grid"><section><h4>Confidentiality</h4><label>Drive encryption<input id="tprmAssessmentEncryption" type="number" min="1" max="5" required></label><label>Access &amp; authentication<input id="tprmAssessmentAccess" type="number" min="1" max="5" required></label><label>Sensitive data access<input id="tprmAssessmentSensitiveData" type="number" min="1" max="5" required></label><label>Confidentiality average<input id="tprmAssessmentConfidentiality" type="number" readonly></label></section><section><h4>Integrity</h4><label>Endpoint protection<input id="tprmAssessmentEndpointProtection" type="number" min="1" max="5" required></label><label>Patch &amp; OS management<input id="tprmAssessmentPatchManagement" type="number" min="1" max="5" required></label><label>User access rights<input id="tprmAssessmentUserAccess" type="number" min="1" max="5" required></label><label>Integrity average<input id="tprmAssessmentIntegrity" type="number" readonly></label></section><section><h4>Availability</h4><label>Storage / data backup<input id="tprmAssessmentBackup" type="number" min="1" max="5" required></label><label>Device management (MDM)<input id="tprmAssessmentMdm" type="number" min="1" max="5" required></label><label>Operational role<input id="tprmAssessmentOperationalRole" type="number" min="1" max="5" required></label><label>Availability average<input id="tprmAssessmentAvailability" type="number" readonly></label></section></div><div class="risk-register-grid"><label>Total CIA score / 100<input id="tprmAssessmentRiskScore" type="number" readonly></label><label>Risk Tier<input id="tprmAssessmentRiskTier" readonly placeholder="Auto-calculated from score"></label></div><table class="tprm-tier-table"><tbody><tr><td>0-40</td><td><strong>High Risk · Tier 1</strong><small>Enhanced due diligence, annual on-site audit, quarterly review, CISO approval before network access.</small></td></tr><tr><td>41-70</td><td><strong>Medium Risk · Tier 2</strong><small>Standard due diligence, annual remote audit, and six-month review.</small></td></tr><tr><td>71-100</td><td><strong>Low Risk · Tier 3</strong><small>Simplified due diligence, annual questionnaire, and audit every three years.</small></td></tr></tbody></table></fieldset><div class="csf-form-actions"><button class="button button-accent" type="submit">Save assessment</button><button class="button button-quiet" id="tprmAssessmentCancel" type="button">Close</button></div></form></dialog>
        </section>
</template>
